#!/usr/bin/env bash
set -euo pipefail
# test-dry-run.sh — smoke test for the dist/ channel.
# Covers: build (archive + SHA256SUMS) → init install → update (checksum
# verified) → [removed] branch + backup restore → tamper detection → overlay
# install preserving host files.  Exit 0 = all checks pass, exit 1 = failure.
#
# Usage: bash dist/test-dry-run.sh
# Run once after any change to dist/*.sh, before shipping to a real host.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
WORK="$(mktemp -d "${TMPDIR_OPENCODE:-/tmp/opencode}/council-dryrun.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

fail() { echo "FAIL: $*"; exit 1; }
pass() { echo "  ok: $*"; }

TS=$(date +%s)
V1="smoke1-$TS"
V2="smoke2-$TS"

# ---------------------------------------------------------------------------
echo "[1/6] build: archive + SHA256SUMS ($V1)"
# ---------------------------------------------------------------------------
bash "$SCRIPT_DIR/build.sh" "$V1" >/dev/null
ARCH1="$SCRIPT_DIR/out/council-dist-$V1.tar.gz"
[[ -f "$ARCH1" ]] || fail "archive not built: $ARCH1"
[[ -f "$SCRIPT_DIR/out/SHA256SUMS" ]] || fail "SHA256SUMS not generated by build.sh"
(cd "$SCRIPT_DIR/out" && sha256sum -c SHA256SUMS >/dev/null) || fail "fresh build checksum mismatch"
# Keep a private copy: the second build.sh run wipes dist/out/.
mkdir -p "$WORK/keep"
cp "$ARCH1" "$WORK/keep/"
ARCH1="$WORK/keep/$(basename "$ARCH1")"
pass "archive built, SHA256SUMS generated and verifies"

# ---------------------------------------------------------------------------
echo "[2/6] init install into empty host"
# ---------------------------------------------------------------------------
mkdir -p "$WORK/d1" "$WORK/host1"
tar xzf "$ARCH1" -C "$WORK/d1"
( cd "$WORK/host1" && bash "$WORK/d1/council-dist/install.sh" \
    --target . --mode init --project-name dryrun-host >/dev/null )
[[ -f "$WORK/host1/.council/version.lock" ]] || fail ".council/version.lock missing"
[[ "$(cat "$WORK/host1/.council/version.lock")" == "$V1" ]] || fail "wrong pinned version"
[[ -f "$WORK/host1/.council/update.sh" ]] || fail ".council/update.sh missing"
[[ -f "$WORK/host1/tools/check_all.py" ]] || fail "core tools not installed"
[[ -f "$WORK/host1/AGENTS.md" ]] || fail "template AGENTS.md not installed"
pass "init install: version.lock=$V1, core + templates present"

# ---------------------------------------------------------------------------
echo "[3/6] update to $V2 with checksum verification"
# ---------------------------------------------------------------------------
bash "$SCRIPT_DIR/build.sh" "$V2" >/dev/null
mkdir -p "$WORK/upd"
cp "$SCRIPT_DIR/out/council-dist-$V2.tar.gz" "$WORK/upd/"
cp "$SCRIPT_DIR/out/SHA256SUMS" "$WORK/upd/"
# Capture output to a variable: `cmd | grep -q` with pipefail would report a
# spurious failure because grep exits early and the producer gets SIGPIPE.
OUT=$( cd "$WORK/host1" && bash .council/update.sh "$WORK/upd/council-dist-$V2.tar.gz" )
echo "$OUT" | grep -q "Checksum OK" || fail "checksum verification did not run"
[[ "$(cat "$WORK/host1/.council/version.lock")" == "$V2" ]] || fail "version not updated"
pass "update: checksum OK, version.lock=$V2"

# ---------------------------------------------------------------------------
echo "[4/6] [removed] branch + backup restore"
# ---------------------------------------------------------------------------
# Build a manifest-less archive variant so update.sh falls back to the host
# manifest and exercises the removal warning path.
mkdir -p "$WORK/nomani" "$WORK/variant"
tar xzf "$WORK/upd/council-dist-$V2.tar.gz" -C "$WORK/nomani"
rm -f "$WORK/nomani/council-dist/core-manifest.txt"
( cd "$WORK/nomani" && tar czf "$WORK/variant/council-dist-$V2.tar.gz" council-dist )
# Pretend the host has an extra core file: create it + list it in the manifest
echo "core" > "$WORK/host1/tools/smoke-extra.txt"
echo "tools/smoke-extra.txt" >> "$WORK/host1/.council/core-manifest.txt"
OUT=$( cd "$WORK/host1" && bash .council/update.sh "$WORK/variant/council-dist-$V2.tar.gz" --force )
echo "$OUT" | grep -q "SHA256SUMS not found" || fail "missing-checksum warning not printed"
echo "$OUT" | grep -q "\[removed\] tools/smoke-extra.txt" || fail "[removed] not reported"
[[ ! -e "$WORK/host1/tools/smoke-extra.txt" ]] || fail "removed file still present"
BACKUP=$( ls -dt "$WORK/host1/.council/backup-"* | head -1 )
( cd "$WORK/host1" && cp -R "$BACKUP"/. . )
[[ -f "$WORK/host1/tools/smoke-extra.txt" ]] || fail "restore from backup failed"
pass "removal warned (backup path shown), file deleted, restore works"

# ---------------------------------------------------------------------------
echo "[5/6] tamper detection (corrupted archive refused)"
# ---------------------------------------------------------------------------
mkdir -p "$WORK/tamper"
cp "$WORK/upd/council-dist-$V2.tar.gz" "$WORK/tamper/"
cp "$WORK/upd/SHA256SUMS" "$WORK/tamper/"
echo "corrupted" >> "$WORK/tamper/council-dist-$V2.tar.gz"
if ( cd "$WORK/host1" && bash .council/update.sh "$WORK/tamper/council-dist-$V2.tar.gz" --force ) 2>&1; then
  fail "corrupted archive was accepted"
fi
pass "corrupted archive refused (checksum failure)"

# ---------------------------------------------------------------------------
echo "[6/6] overlay install preserves host files"
# ---------------------------------------------------------------------------
mkdir -p "$WORK/host2"
echo "HOST CUSTOM AGENTS CONTENT" > "$WORK/host2/AGENTS.md"
echo "keep me" > "$WORK/host2/README.md"
mkdir -p "$WORK/d2"
tar xzf "$ARCH1" -C "$WORK/d2"
OUT=$( cd "$WORK/host2" && bash "$WORK/d2/council-dist/install.sh" \
  --target . --mode overlay --project-name dryrun-overlay )
echo "$OUT" | grep -q "OVERLAY mode" || fail "overlay mode note missing"
grep -q "HOST CUSTOM AGENTS CONTENT" "$WORK/host2/AGENTS.md" || fail "overlay overwrote host file"
[[ -f "$WORK/host2/README.md" ]] || fail "overlay deleted host file"
[[ -f "$WORK/host2/tools/check_all.py" ]] || fail "overlay did not install core"
pass "overlay: note printed, host files preserved, core installed"

echo ""
echo "DRY-RUN PASSED"
